fn adj_of(adj: Map[Str, List[Str]], key: Str) -> List[Str] {
  let none_list: List[Str] = []
  return adj.get(key).unwrap_or(none_list)
}

pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  var names: List[Str] = []
  var adj: Map[Str, List[Str]] = Map {}
  for p in pairs {
    let a = p.get_or(0, "")
    let b = p.get_or(1, "")
    names = names.push(a).push(b)
    adj = adj.set(a, adj_of(adj, a).push(b))
    adj = adj.set(b, adj_of(adj, b).push(a))
  }
  let sorted_names = names.unique().sort()
  var seen: Map[Str, Bool] = Map {}
  var out: List[List[Str]] = []
  for start in sorted_names {
    if not seen.has(start) {
      seen = seen.set(start, true)
      var comp: List[Str] = [start]
      var qi = 0
      while qi < comp.len() {
        let cur = comp.get_or(qi, "")
        qi = qi + 1
        for nb in adj_of(adj, cur) {
          if not seen.has(nb) {
            seen = seen.set(nb, true)
            comp = comp.push(nb)
          }
        }
      }
      out = out.push(comp.sort())
    }
  }
  return out
}
